git mv comun/brazos.py comun/variantes.py && git mv tests/test_brazos.py tests/test_variantes.py && cat > scripts/_reemplazo_d1.pl <<'EOF'
s/\bdel brazo\b/de la variante/g; s/\bal brazo\b/a la variante/g;
s/\b([Ee])l brazo\b/$1 eq "E" ? "La variante" : "la variante"/ge;
s/\b([Uu])n brazo\b/$1 eq "U" ? "Una variante" : "una variante"/ge;
s/\bdel brazo\b/de la variante/g;
s/\blos brazos\b/las variantes/g; s/\bLos brazos\b/Las variantes/g;
s/\bde brazos\b/de variantes/g; s/\bdelos\b/delos/g;
s/BRAZOS/VARIANTES/g; s/Brazos/Variantes/g; s/Brazo/Variante/g;
s/brazos/variantes/g; s/brazo/variante/g;
EOF
for f in comun/*.py tests/*.py scripts/separar_ledger.py scripts/vm.sh experimentos/sampling_1/scripts/graficar.py experimentos/sampling_1/scripts/ledger_parcial.py; do case $f in comun/tokens.py) continue;; esac; perl -pi scripts/_reemplazo_d1.pl $f; done; rm scripts/_reemplazo_d1.pl; git grep -n -i brazo -- comun scripts tests experimentos/sampling_1/scripts
